def _safe_md(text):
    """Render text safely — wrap in HTML pre block to prevent markdown heading parsing."""
    if not text:
        return text
    import html
    escaped = html.escape(text)
    escaped = escaped.replace("\n", "<br>")
    return escaped

def _render_field(label, text):
    """Render a control field with label, immune to markdown parsing."""
    import html
    safe = html.escape(text or "").replace("\n", "<br>")
    st.markdown(
        f'<div style="margin-bottom:10px;">' +
        f'<div style="font-weight:600;font-size:.82rem;color:#2e2e38;margin-bottom:3px;">{label}</div>' +
        f'<div style="font-size:.82rem;color:#444;line-height:1.55;">{safe}</div></div>',
        unsafe_allow_html=True
    )

