# ══════════════════════════════════════════════
#  TAB 4 — GAP TRACKER
# ══════════════════════════════════════════════
with tab4:
    # All required controls to assess = 13 always-required + conditional required
    all_tracker_ctrls = (
        [{"id": c["id"], "name": c["name"], "domain": c["domain"],
          "objective": c["objective"], "always": True} for c in ALWAYS] +
        [{"id": r["id"], "name": r["name"], "domain": r["domain"],
          "objective": r["objective"], "always": False, "gap": r["gap"]}
         for r in results if r["status"] == "Required"]
    )

    n_tracker_total  = len(all_tracker_ctrls)
    n_tracker_yes    = sum(1 for c in all_tracker_ctrls if get_impl(c["id"]) == "Yes")
    n_tracker_no     = sum(1 for c in all_tracker_ctrls if get_impl(c["id"]) == "No")
    n_tracker_unsure = sum(1 for c in all_tracker_ctrls if get_impl(c["id"]) not in ["Yes", "No"])
    all_assessed     = (n_tracker_unsure == 0)

    g1, g2, g3, g4 = st.columns(4)
    metric(g1, n_tracker_total,  "Controls to Assess", "yellow")
    metric(g2, n_tracker_yes,    "Implemented",         "")
    metric(g3, n_tracker_no,     "Gaps",                "red")
    metric(g4, n_tracker_unsure, "Not Yet Assessed",    "gray")

    st.markdown("<div style='margin-top:20px;'></div>", unsafe_allow_html=True)
    st.markdown(
        '<div style="background:#fff8cc;border:1px solid #ffe066;border-radius:4px;'
        'padding:14px 16px;margin-bottom:16px;font-size:.82rem;color:#7a5c00;line-height:1.6;">'
        '<strong>How to complete this step:</strong><br>'
        'For each control below, click <strong>View monitoring details</strong> to see the monitoring objective, '
        'indicators to verify, and evidence to request — all directly inline without switching tabs.<br><br>'
        'Then assess the evidence you have received or currently hold from your provider. '
        'Based on that review, mark each control <strong>Yes</strong> (the control is implemented and '
        'evidence is available to support it) or <strong>No</strong> (the control is missing, '
        'incomplete, or evidence cannot be obtained — this constitutes a gap).<br><br>'
        'Use the <strong>Comment</strong> field under each control to record your reasoning, '
        'note the evidence reviewed, flag blockers, or document any partial implementation. '
        'These notes will be included in the exported tracker to support remediation follow-up.<br><br>'
        '<strong>All controls must be assessed (Yes or No) before you can export.</strong>'
        '</div>',
        unsafe_allow_html=True
    )

    # Group all tracker controls by domain, preserving order
    by_domain_tracker = defaultdict(list)
    for c in all_tracker_ctrls:
        by_domain_tracker[c["domain"]].append(c)

    for domain, ctrls in by_domain_tracker.items():
        label       = DOMAIN_META.get(domain, (domain, ""))[0]
        always_cnt  = sum(1 for c in ctrls if c["always"])
        cond_cnt    = sum(1 for c in ctrls if not c["always"])
        sub_parts   = []
        if always_cnt: sub_parts.append(f"{always_cnt} always required")
        if cond_cnt:   sub_parts.append(f"{cond_cnt} conditional")
        st.markdown(
            f'<div style="background:#ffffff;border:1px solid #e0e0eb;border-left:4px solid #2e2e38;'
            f'border-radius:4px;padding:8px 14px;margin:14px 0 6px 0;font-weight:600;font-size:.88rem;'
            f'color:#2e2e38;display:flex;justify-content:space-between;align-items:center;">'
            f'<span>{label}</span>'
            f'<span style="font-size:.72rem;color:#6e6e79;font-weight:400;">{" · ".join(sub_parts)}</span>'
            f'</div>',
            unsafe_allow_html=True
        )
        for ctrl in ctrls:
            impl_val = get_impl(ctrl["id"])
            if impl_val == "No":
                dot = '<span style="color:#c4262e;font-weight:700;">&#9679;</span>'
            elif impl_val == "Yes":
                dot = '<span style="color:#2e2e38;font-weight:700;">&#9679;</span>'
            else:
                dot = '<span style="color:#c8c8d0;font-weight:700;">&#9679;</span>'

            type_badge = (
                '<span style="background:#2e2e38;color:#ffe600;font-size:.62rem;font-weight:700;'
                'padding:1px 6px;border-radius:2px;margin-right:6px;">ALWAYS</span>'
                if ctrl["always"] else
                '<span style="background:#fff8cc;color:#7a5c00;font-size:.62rem;font-weight:700;'
                'padding:1px 6px;border-radius:2px;margin-right:6px;">CONDITIONAL</span>'
            )

            # Control header row
            st.markdown(
                f'{dot} &nbsp;{type_badge}<strong>{ctrl["id"]}</strong> &mdash; {ctrl["name"]}',
                unsafe_allow_html=True
            )
            # Radio buttons — Yes / No / Not assessed — horizontal
            radio_idx = {"Yes": 0, "No": 1, "Not assessed": 2}.get(impl_val, 2)
            st.radio(
                "Implementation status",
                options=["Yes", "No", "Not assessed"],
                index=radio_idx,
                key=f"impl_{ctrl['id']}",
                horizontal=True,
                label_visibility="collapsed",
            )
            with st.expander("View monitoring details"):
                st.markdown(f"**Monitoring Objective**")
                st.markdown(ctrl["objective"])
                if ctrl.get("indicators"):
                    st.markdown(f"**Suggested Indicators**")
                    st.markdown(ctrl["indicators"])
                if ctrl.get("evidence"):
                    st.markdown(f"**Evidence Examples**")
                    st.markdown(ctrl["evidence"])
            st.text_area(
                "Comment",
                value=st.session_state.get(f"comment_{ctrl['id']}", ""),
                placeholder="Record the evidence reviewed, your reasoning, any blockers, or partial implementation notes...",
                key=f"comment_{ctrl['id']}",
                height=68,
                label_visibility="collapsed",
            )
            st.markdown('<hr style="margin:6px 0;border-color:#f0f0f5;">', unsafe_allow_html=True)
    # ── Export & Finish at bottom of gap tracker ──
    st.markdown("<div style='margin-top:24px;'></div>", unsafe_allow_html=True)
    st.markdown('<hr style="border-color:#e0e0eb;">', unsafe_allow_html=True)

    if not all_assessed:
        remaining = n_tracker_unsure
        st.markdown(
            f'<div style="background:#f8f8fc;border:1px solid #e0e0eb;border-radius:4px;'
            f'padding:12px 16px;margin-bottom:12px;font-size:.82rem;color:#6e6e79;text-align:center;">'
            f'<strong style="color:#2e2e38;">{remaining} control{"s" if remaining != 1 else ""} not yet assessed.</strong>'
            f' Mark all controls Yes or No before exporting.'
            f'</div>',
            unsafe_allow_html=True
        )
        st.button("Export & Finish", use_container_width=True, disabled=True)
    else:
        st.markdown(
            '<div style="background:#e6f6f5;border:1px solid #9ed8d3;border-radius:4px;'
            'padding:10px 16px;margin-bottom:12px;font-size:.82rem;color:#2e2e38;">'
            f'All {n_tracker_total} controls assessed. '
            f'<strong>{n_tracker_no} gap{"s" if n_tracker_no != 1 else ""} identified.</strong> '
            'Ready to export.'
            '</div>',
            unsafe_allow_html=True
        )
        if st.button("Export & Finish", use_container_width=True):
            show_export_disclaimer()

        if st.session_state.get("export_confirmed"):
            st.session_state.pop("export_confirmed", None)
            data  = build_excel()
            fname = f"SMF_{case_id or 'Assessment'}.xlsx"
            st.download_button(
                label="Download Assessment Workbook (.xlsx)",
                data=data,
                file_name=fname,
                mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                use_container_width=True,
            )
            st.success(f"Report ready: {fname}")